"clear all

% Nominal longitudinal model parameters
V  = 710.0;   Xu = -0.0066; Xw = 0.039;
Zu = -0.032;  Zw = -0.72;
Mw = -0.0053; Mq = -0.9;   g  = 32.174;

% Nominal state matrix
A_nom = [Xu, Xw, 0,  -g ;
         Zu, Zw, V,   0 ;
         0,  Mw, Mq,  0 ;
         0,  0,  1,   0 ];

% Input matrix
B = [0; -6.0; -4.0; 0];

% Open-loop eigenvalues
eig_ol = eig(A_nom);

% Identify phugoid poles (smallest |imag|)
[~, sort_idx] = sort(abs(imag(eig_ol)));
ph_ol = eig_ol(sort_idx(1:2));

% Desired short-period poles
wn = 2.0; z = 0.6;
sp_des = [-z*wn + 1j*wn*sqrt(1-z^2);
          -z*wn - 1j*wn*sqrt(1-z^2)];

% Pole placement: short-period at desired, phugoid held at open-loop
P = [sp_des; ph_ol];
K = place(A_nom, B, P);

% Monte Carlo over N=200 deterministic samples
N   = 200;
pct = 0.25;

rng(20260827);
f_Mw = 1 + pct*(2*rand(N,1) - 1);
rng(20261827);
f_Zw = 1 + pct*(2*rand(N,1) - 1);
rng(20262827);
f_Mq = 1 + pct*(2*rand(N,1) - 1);

count = 0;
for i = 1:N
    A_i = A_nom;
    A_i(2,2) = Zw * f_Zw(i);   % perturb Zw
    A_i(3,2) = Mw * f_Mw(i);   % perturb Mw
    A_i(3,3) = Mq * f_Mq(i);   % perturb Mq

    eig_cl = eig(A_i - B*K);

    % Identify the short-period pair (largest |imag|)
    [~, idx_sp] = sort(abs(imag(eig_cl)), 'descend');
    sp_poles = eig_cl(idx_sp(1:2));

    wn_sp   = abs(sp_poles(1));
    zeta_sp = -real(sp_poles(1)) / wn_sp;

    if (wn_sp >= 1.88 && wn_sp <= 2.12 && zeta_sp >= 0.51)
        count = count + 1;
    end
end

result.pass_fraction      = count / N;
result.failing_case_count = N - count;

fid = fopen('result.json', 'w');
fwrite(fid, jsonencode(result));
fclose(fid);"
